"""Minimal reproducible starting candidate for open-ended BBBC036 discovery.

This is intentionally a weak, conventional starting point.  It concatenates
the protected executor inputs and predicts the registered joint CP/L1000
response with one MLP.  It does not pre-install multi-tower fusion,
assay-specific heads, mixed PCC--MSE objectives, AdamW, or a scheduler; those
remain hypotheses that the discovery process must propose and test.
"""

import torch
from torch import nn


def candidate_metadata():
    return {
        "schema_version": "cellscientist_open_candidate_v1",
        "candidate_name": "bbbc036_concat_mlp_h0",
        "semantic_components": [
            "perturbation.joint_input_fusion",
            "response.shared_program",
            "response.joint_readout",
            "objective.response_loss",
            "optimization.optimizer",
        ],
        "component_symbols": {
            "perturbation.joint_input_fusion": ["ConcatenationFusion"],
            "response.shared_program": ["SharedResponseProgram"],
            "response.joint_readout": ["JointResponseReadout"],
            "objective.response_loss": ["compute_loss"],
            "optimization.optimizer": ["build_optimizer"],
        },
        "change_summary": "Initial reproducible concatenation-MLP candidate.",
    }


class ConcatenationFusion(nn.Module):
    def forward(self, pre, chemical, dose):
        return torch.cat((pre, chemical, dose), dim=1)


class SharedResponseProgram(nn.Module):
    def __init__(self, input_dim, hidden_dim):
        super().__init__()
        self.network = nn.Sequential(
            nn.Linear(input_dim, hidden_dim),
            nn.ReLU(),
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
        )

    def forward(self, fused):
        return self.network(fused)


class JointResponseReadout(nn.Module):
    def __init__(self, hidden_dim, target_dim):
        super().__init__()
        self.projection = nn.Linear(hidden_dim, target_dim)

    def forward(self, hidden):
        return self.projection(hidden)


class ConcatenationMLP(nn.Module):
    def __init__(self, task_spec):
        super().__init__()
        input_dim = (
            int(task_spec["context_dim"])
            + int(task_spec["chemical_dim"])
            + int(task_spec["dose_dim"])
        )
        target_dim = int(task_spec["target_dim"])
        hidden_dim = 256
        self.fusion = ConcatenationFusion()
        self.response_program = SharedResponseProgram(input_dim, hidden_dim)
        self.readout = JointResponseReadout(hidden_dim, target_dim)

    def forward(self, pre, chemical, dose):
        fused = self.fusion(pre, chemical, dose)
        hidden = self.response_program(fused)
        return self.readout(hidden)


def build_model(task_spec):
    return ConcatenationMLP(task_spec)


def compute_loss(prediction, target, state):
    del state
    return torch.nn.functional.mse_loss(prediction, target)


def build_optimizer(model, state):
    del state
    return torch.optim.Adam(model.parameters(), lr=1e-3)


def build_scheduler(optimizer, state):
    del optimizer, state
    return None
